'use strict';

// Generated by inspecting the game's native daily-standing method and config
// constructor. The server's PlayerLevel is that method's allowance input; it
// does not replace the separately calculated mastery rank shown by the app.
const RULES = require('../data/affiliation-rules.json');
const amount = value => Number.isSafeInteger(value) && value >= 0;
const validRules = value => value?.schema === 1 && amount(value.base) && amount(value.perRank)
  && value.base > 0 && value.base <= 1000000 && value.perRank <= 1000000;

function dailyAffiliationProgress(inventory, field = 'DailyAffiliation', rules = RULES) {
  if (!['DailyAffiliation', 'DailyAffiliationOde'].includes(field) || !amount(inventory?.[field])) return null;
  const remaining = inventory[field];
  const rank = amount(inventory.PlayerLevel) && inventory.PlayerLevel <= 65535 ? inventory.PlayerLevel : null;
  const calculated = rank === null || !validRules(rules) ? null : rules.base + rank * rules.perRank;
  // Never discard a server balance when its rank or the formula is unavailable
  // or inconsistent. Remaining is exact even when a percentage cannot be known.
  const cap = calculated !== null && remaining <= calculated ? calculated : null;
  return { remaining, cap, earned: cap === null ? null : cap - remaining };
}

module.exports = { dailyAffiliationProgress };
